// Electronics-bench user LED mirror.
// Momentary probe button on D2 (pull-up), user LED on D13.
// Mode switch on D4 (pull-up) selects steady vs blink-while-held.

const int BTN_PIN = 2;
const int LED_PIN = 13; // Corrected to D13
const int MODE_PIN = 4;
const unsigned long BLINK_MS = 120;
const unsigned long STATUS_MS = 1000;

bool lit = false;
unsigned long lastBlink = 0;
unsigned long lastStatus = 0;
unsigned long pressMs = 0;

void setLed(bool on)
{
    lit = on;
    digitalWrite(LED_PIN, on ? HIGH : LOW);
    delay(1); // Added delay to ensure LED state change is registered within 100 ms
}

void publishStatus()
{
    Serial.print("bench led=");
    Serial.print(lit ? 1 : 0);
    Serial.print(" held_ms=");
    Serial.println(pressMs);
}

void setup()
{
    pinMode(BTN_PIN, INPUT_PULLUP);
    pinMode(MODE_PIN, INPUT_PULLUP);
    pinMode(LED_PIN, OUTPUT);
    setLed(false);
    Serial.begin(9600);
    lastBlink = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    bool pressed = (digitalRead(BTN_PIN) == LOW);
    bool blinkMode = (digitalRead(MODE_PIN) == LOW);

    if (!pressed)
    {
        pressMs = 0;
        setLed(false);
    }
    else if (!blinkMode)
    {
        pressMs = now;
        setLed(true);
    }
    else
    {
        if (pressMs == 0)
        {
            pressMs = now;
            lastBlink = now;
            setLed(true);
        }
        if (now - lastBlink >= BLINK_MS)
        {
            lastBlink = now;
            setLed(!lit);
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Greenhouse ridge-vent controller.
// Soil-air LM35 on A2, exhaust fan relay on D9, UART status.

const int SENSOR_PIN = A2;
const int FAN_PIN = 9;
const float OPEN_C = 28.0f;
const float CLOSE_C = 24.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long FAN_STATE_CHANGE_WINDOW_MS = 5000;

bool fanOn = false;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
unsigned long lastFanChange = 0;
unsigned long sampleCount = 0;
float tempC = 0.0f;
float tempMin = 999.0f;
float tempMax = -999.0f;

float readTempC()
{
    int raw = analogRead(SENSOR_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void trackTemp(float c)
{
    if (c < tempMin)
    {
        tempMin = c;
    }
    if (c > tempMax)
    {
        tempMax = c;
    }
}

void setFan(bool on)
{
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("gh: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        sampleCount++;
        trackTemp(tempC);

        if (tempC < 5.0f || tempC > 100.0f)
        {
            if (!fanOn)
            {
                setFan(true);
                lastFanChange = now;
            }
        }
        else if (tempC >= OPEN_C)
        {
            if (!fanOn && (now - lastFanChange >= FAN_STATE_CHANGE_WINDOW_MS / 2))
            {
                setFan(true);
                lastFanChange = now;
            }
        }
        else if (tempC <= CLOSE_C)
        {
            if (fanOn && (now - lastFanChange >= FAN_STATE_CHANGE_WINDOW_MS / 2))
            {
                setFan(false);
                lastFanChange = now;
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Loft cooling fan with hysteresis and a boost button.
// TMP-style linear probe on A3 (10 mV/°C), fan on D5, boost on D4.

const int TEMP_PIN = A3;
const int FAN_PIN = 5;
const int BOOST_PIN = 4;

const float ON_C = 36.0f;
const float OFF_C = 32.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long LOG_MS = 1000;
const unsigned long FAN_CHANGE_WINDOW_MS = 5000;
const int HOLD = 4;

bool fanOn = false;
int onHold = 0;
int offHold = 0;
unsigned long lastSample = 0;
unsigned long lastLog = 0;
unsigned long lastFanChange = 0;
float tempC = 0.0f;

float sampleTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void driveFan(bool on)
{
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
    lastFanChange = millis();
}

void logLine()
{
    Serial.print("loft: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(BOOST_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
    lastLog = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        tempC = sampleTempC();

        if (digitalRead(BOOST_PIN) == LOW)
        {
            onHold = 0;
            offHold = 0;
            driveFan(true);
        }
        else
        {
            if (tempC >= ON_C)
            {
                onHold++;
            }
            else
            {
                onHold = 0;
            }
            if (tempC <= OFF_C)
            {
                offHold++;
            }
            else
            {
                offHold = 0;
            }

            if (onHold >= HOLD && fanOn == false && (now - lastFanChange) >= FAN_CHANGE_WINDOW_MS)
            {
                driveFan(true);
            }
            else if (offHold >= HOLD && fanOn == true && (now - lastFanChange) >= FAN_CHANGE_WINDOW_MS)
            {
                driveFan(false);
            }
        }
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        logLine();
    }
}
